import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry the_entry_name(
    .param .u64 inp_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 Hin,
    .param .u32 Win,
    .param .u32 Cout,
    .param .u32 KH,
    .param .u32 KW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 Hout,
    .param .u32 Wout
)
    .maxnreg 256
    {
    .reg .pred %p_exit, %p, %p_same, %p_cin3, %p_vec_ok, %p_and;
    .reg .b32 %r_tid, %r_tmp0, %r_tmp1, %r_cta;
    .reg .b32 %r_total, %rN, %rCin, %rHin, %rWin, %rCout, %rKH, %rKW, %rSh, %rSw, %rPh, %rPw, %rHout, %rWout;
    .reg .b32 %r_grid, %r_stride, %r_tcur;
    .reg .b32 %r_rem0, %r_rem1, %r_rem2, %r_wo, %r_ho, %r_co, %r_n;
    .reg .b32 %r_t0, %r_t1, %r_t2, %r_t3, %r_t4, %r_t5;
    .reg .b32 %r_wbase_s32, %r_hbase_s32, %r_hin_s32, %r_win_s32;
    .reg .b32 %r_c, %r_kh, %r_kw;
    .reg .b32 %r_idx_nc, %r_idx_nch, %r_in_base, %r_win_u32;
    .reg .b32 %r_w_cc, %r_w_cch, %r_w_base_idx;
    .reg .b64 %rd_inp, %rd_w, %rd_b, %rd_out, %addr_inp, %addr_w, %addr_out, %ofs_bytes, %addr_bias;
    .reg .f32 %f_acc, %f_in, %f_w, %f_bias;
    // Additional registers for cooperative weight staging
    .reg .b32 %r_btid, %r_co0, %r_total_w, %r_load_idx, %r_cksz, %r_c_tmp, %r_rem_ck, %r_kh_tmp, %r_kw_tmp, %r_w_local_base_idx;
    .reg .b64 %rd_smem_base, %addr_smem;
    // New regs for kw range clipping
    .reg .b32 %r_kw_lo, %r_kw_hi, %r_tmpk0, %r_tmpk1;
    // New regs for kh range clipping
    .reg .b32 %r_kh_lo, %r_kh_hi, %r_tmpkh0, %r_tmpkh1;
    // Additional vectorization registers
    .reg .f32 %f_v1, %f_v2, %f_v3, %f_w0, %f_w1, %f_w2, %f_w3;
    .reg .b32 %r_kwp4, %r_align, %r_wloc_base_kw, %r_wglob_base_kw;
    // Fast-path (Cin==3) additional registers
    .reg .b32 %r_idx_nc_base, %r_idx_nch_c0, %r_idx_nch_c1, %r_idx_nch_c2;
    .reg .b32 %r_in_base_c0, %r_in_base_c1, %r_in_base_c2;
    .reg .b32 %r_w_base_idx_c0, %r_w_base_idx_c1, %r_w_base_idx_c2;
    .reg .b32 %r_w_local_base_idx_c0, %r_w_local_base_idx_c1, %r_w_local_base_idx_c2;
    .reg .b32 %r_wglob_base_kw_c0, %r_wglob_base_kw_c1, %r_wglob_base_kw_c2;
    .reg .b32 %r_wloc_base_kw_c0, %r_wloc_base_kw_c1, %r_wloc_base_kw_c2;
    // Vectorized cp.async registers
    .reg .b32 %r_wco_base, %r_total_w4, %r_load_idx4, %r_step4, %r_wco_bytes, %r_mod16;
    // Shared memory for weight tile: 3*11*11 floats = 363*4 = 1452 bytes (rounded up)
    .shared .align 16 .b8 smem_w[1472];
    // Load parameters
    ld.param.u64 %rd_inp, [inp_ptr];
    ld.param.u64 %rd_w,   [w_ptr];
    ld.param.u64 %rd_b,   [b_ptr];
    ld.param.u64 %rd_out, [out_ptr];
    ld.param.u32 %rN,     [N];
    ld.param.u32 %rCin,   [Cin];
    ld.param.u32 %rHin,   [Hin];
    ld.param.u32 %rWin,   [Win];
    ld.param.u32 %rCout,  [Cout];
    ld.param.u32 %rKH,    [KH];
    ld.param.u32 %rKW,    [KW];
    ld.param.u32 %rSh,    [stride_h];
    ld.param.u32 %rSw,    [stride_w];
    ld.param.u32 %rPh,    [pad_h];
    ld.param.u32 %rPw,    [pad_w];
    ld.param.u32 %rHout,  [Hout];
    ld.param.u32 %rWout,  [Wout];
    // Compute global linear thread id
    mov.u32 %r_tmp0, %tid.x;
    mov.u32 %r_tmp1, %ntid.x;
    mov.u32 %r_cta,  %ctaid.x;
    mad.lo.u32 %r_tid, %r_cta, %r_tmp1, %r_tmp0;
    mov.u32 %r_grid, %nctaid.x;
    mul.lo.u32 %r_stride, %r_grid, %r_tmp1;
    // total = N * Cout * Hout * Wout
    mul.lo.u32 %r_t0, %rN, %rCout;
    mul.lo.u32 %r_t1, %rHout, %rWout;
    mul.lo.u32 %r_total, %r_t0, %r_t1;
    // Decompose tid into (n, co, ho, wo) for NCHW layout with Cout as second dim
    mov.u32 %r_rem0, %r_tid;
    rem.u32 %r_wo, %r_rem0, %rWout;
    div.u32 %r_rem1, %r_rem0, %rWout;
    rem.u32 %r_ho, %r_rem1, %rHout;
    div.u32 %r_rem2, %r_rem1, %rHout;
    rem.u32 %r_co, %r_rem2, %rCout;
    div.u32 %r_n,  %r_rem2, %rCout;
    // Compute base thread id for the CTA and derive co0 (Cout index shared by most threads in the block)
    mul.lo.u32 %r_btid, %r_cta, %r_tmp1;          // base tid of CTA
    mov.u32 %r_rem0, %r_btid;
    // wo0 = btid % Wout
    rem.u32 %r_t0, %r_rem0, %rWout;
    div.u32 %r_rem1, %r_rem0, %rWout;
    // ho0 = rem1 % Hout
    rem.u32 %r_t1, %r_rem1, %rHout;
    div.u32 %r_rem2, %r_rem1, %rHout;
    // co0 = rem2 % Cout
    rem.u32 %r_co0, %r_rem2, %rCout;
    // n0 = rem2 / Cout (unused)
    // Cooperative staging of weights for co0 into shared memory
    mul.lo.u32 %r_cksz, %rKH, %rKW;               // KH*KW
    mul.lo.u32 %r_total_w, %rCin, %r_cksz;        // Cin*KH*KW
    mov.u64 %rd_smem_base, smem_w;
    // Vectorized cp.async staging: 16B copies for main, 4B for tail
    // r_wco_base = co0 * total_w
    mul.lo.u32 %r_wco_base, %r_co0, %r_total_w;
    // total_w4 = (total_w >> 2) << 2
    // Check 16B alignment of global weight base; if misaligned, fall back to 4B cp.async
    shl.b32 %r_wco_bytes, %r_wco_base, 2;
    and.b32 %r_mod16, %r_wco_bytes, 15;
    setp.eq.u32 %p_vec_ok, %r_mod16, 0;
    @!%p_vec_ok bra L_sload_scalar_all;
    shr.u32 %r_t0, %r_total_w, 2;
    shl.b32 %r_total_w4, %r_t0, 2;
    // step4 = blockDim.x * 4
    shl.b32 %r_step4, %r_tmp1, 2;
    // load_idx4 = tid.x * 4
    shl.b32 %r_load_idx4, %r_tmp0, 2;
L_sload_vec:
    setp.ge.u32 %p, %r_load_idx4, %r_total_w4;
    @%p bra L_sload_vec_done;
    // Global address for 16B chunk
    add.u32 %r_t2, %r_wco_base, %r_load_idx4;
    mul.wide.u32 %ofs_bytes, %r_t2, 4;
    add.s64 %addr_w, %rd_w, %ofs_bytes;
    // Shared memory address for 16B chunk
    mul.wide.u32 %ofs_bytes, %r_load_idx4, 4;
    add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
    cp.async.ca.shared.global [%addr_smem], [%addr_w], 16;
    add.u32 %r_load_idx4, %r_load_idx4, %r_step4;
    bra L_sload_vec;
L_sload_vec_done:
    // Tail: 4B cp.async for remaining elements
    add.u32 %r_load_idx, %r_total_w4, %r_tmp0;
L_sload_tail:
    setp.ge.u32 %p, %r_load_idx, %r_total_w;
    @%p bra L_sload_done;
    add.u32 %r_t2, %r_wco_base, %r_load_idx;
    mul.wide.u32 %ofs_bytes, %r_t2, 4;
    add.s64 %addr_w, %rd_w, %ofs_bytes;
    mul.wide.u32 %ofs_bytes, %r_load_idx, 4;
    add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
    cp.async.ca.shared.global [%addr_smem], [%addr_w], 4;
    add.u32 %r_load_idx, %r_load_idx, %r_tmp1;
    bra L_sload_tail;
L_sload_scalar_all:
    // Scalar 4B cp.async staging for entire tile when global base is not 16B-aligned
    mov.u32 %r_load_idx, %r_tmp0;
L_sload_scalar_loop_all:
    setp.ge.u32 %p, %r_load_idx, %r_total_w;
    @%p bra L_sload_scalar_end_all;
    add.u32 %r_t2, %r_wco_base, %r_load_idx;
    mul.wide.u32 %ofs_bytes, %r_t2, 4;
    add.s64 %addr_w, %rd_w, %ofs_bytes;
    mul.wide.u32 %ofs_bytes, %r_load_idx, 4;
    add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
    cp.async.ca.shared.global [%addr_smem], [%addr_w], 4;
    add.u32 %r_load_idx, %r_load_idx, %r_tmp1;
    bra L_sload_scalar_loop_all;
L_sload_scalar_end_all:
    bra L_sload_done;
L_sload_done:
    // Commit and wait for async copies before proceeding
    cp.async.commit_group;
    cp.async.wait_group 0;
    bar.sync 0;
    // Early-exit after cooperative weight staging to avoid barrier divergence
    // Start grid-stride loop over output elements
    mov.u32 %r_tcur, %r_tid;
L_t_loop:
    setp.ge.u32 %p_exit, %r_tcur, %r_total;
    @%p_exit bra DONE;
    // Decompose linear index r_tcur into (n, co, ho, wo)
    mov.u32 %r_rem0, %r_tcur;
    rem.u32 %r_wo, %r_rem0, %rWout;
    div.u32 %r_rem1, %r_rem0, %rWout;
    rem.u32 %r_ho, %r_rem1, %rHout;
    div.u32 %r_rem2, %r_rem1, %rHout;
    rem.u32 %r_co, %r_rem2, %rCout;
    div.u32 %r_n,  %r_rem2, %rCout;
    // acc = bias[co]
    mul.wide.u32 %ofs_bytes, %r_co, 4;
    add.s64 %addr_bias, %rd_b, %ofs_bytes;
    ld.global.f32 %f_bias, [%addr_bias];
    mov.f32 %f_acc, %f_bias;
    // wbase = (int)wo * stride_w - (int)pad_w
    mul.lo.u32 %r_t0, %r_wo, %rSw;
    cvt.s32.u32 %r_t1, %r_t0;
    cvt.s32.u32 %r_t2, %rPw;
    sub.s32 %r_wbase_s32, %r_t1, %r_t2;
    // hbase = (int)ho * stride_h - (int)pad_h
    mul.lo.u32 %r_t0, %r_ho, %rSh;
    cvt.s32.u32 %r_t1, %r_t0;
    cvt.s32.u32 %r_t2, %rPh;
    sub.s32 %r_hbase_s32, %r_t1, %r_t2;
    // Determine if this thread shares co with CTA base (enables shared-memory weights)
    setp.eq.u32 %p_same, %r_co, %r_co0;
    // Compute valid kh range to avoid per-iteration h_in bounds checks
    mov.u32 %r_kh_lo, 0;
    setp.lt.s32 %p, %r_hbase_s32, 0;
    sub.s32 %r_tmpkh0, 0, %r_hbase_s32;
    cvt.u32.s32 %r_tmpkh1, %r_tmpkh0;
    @!%p bra L_khlo_done;
    setp.gt.u32 %p, %r_tmpkh1, %rKH;
    @%p mov.u32 %r_kh_lo, %rKH;
    @!%p mov.u32 %r_kh_lo, %r_tmpkh1;
    bra L_khlo_done;
L_khlo_done:
    cvt.s32.u32 %r_t4, %rHin;
    sub.s32 %r_tmpkh0, %r_t4, %r_hbase_s32;
    setp.le.s32 %p, %r_tmpkh0, 0;
    @%p mov.u32 %r_kh_hi, 0;
    @%p bra L_khhi_done;
    cvt.u32.s32 %r_tmpkh1, %r_tmpkh0;
    setp.gt.u32 %p, %r_tmpkh1, %rKH;
    @%p mov.u32 %r_kh_hi, %rKH;
    @!%p mov.u32 %r_kh_hi, %r_tmpkh1;
L_khhi_done:
    // Fast path if Cin == 3: unroll channel loop
    setp.eq.u32 %p_cin3, %rCin, 3;
    @%p_cin3 bra L_fast_cin3;
    // Loop over input channels c (generic path)
    mov.u32 %r_c, 0;
L_c_loop:
    setp.ge.u32 %p, %r_c, %rCin;
    @%p bra L_end_c;
    // (co*Cin + c)
    mul.lo.u32 %r_w_cc, %r_co, %rCin;
    add.u32 %r_w_cc, %r_w_cc, %r_c;
    // idx_nc = n*Cin + c
    mul.lo.u32 %r_idx_nc, %r_n, %rCin;
    add.u32 %r_idx_nc, %r_idx_nc, %r_c;
    // Loop over kernel height kh
    mov.u32 %r_kh, %r_kh_lo;
L_kh_loop:
    setp.ge.u32 %p, %r_kh, %r_kh_hi;
    @%p bra L_end_kh;
    // h_in = hbase + kh
    cvt.s32.u32 %r_t0, %r_kh;
    add.s32 %r_hin_s32, %r_hbase_s32, %r_t0;
    // if (h_in < 0 || h_in >= Hin) skip inner loop (never taken due to kh clipping)
    setp.lt.s32 %p, %r_hin_s32, 0;
    @%p bra L_skip_h;
    cvt.s32.u32 %r_t1, %rHin;
    setp.ge.s32 %p, %r_hin_s32, %r_t1;
    @%p bra L_skip_h;
    // in_base = ((idx_nc * Hin) + (u32)h_in) * Win
    mul.lo.u32 %r_idx_nch, %r_idx_nc, %rHin;
    cvt.u32.s32 %r_t2, %r_hin_s32;
    add.u32 %r_idx_nch, %r_idx_nch, %r_t2;
    mul.lo.u32 %r_in_base, %r_idx_nch, %rWin;
    // w_base_idx for global path: (((co*Cin + c) * KH) + kh) * KW
    mul.lo.u32 %r_w_cch, %r_w_cc, %rKH;
    add.u32 %r_w_cch, %r_w_cch, %r_kh;
    mul.lo.u32 %r_w_base_idx, %r_w_cch, %rKW;
    // w_local_base_idx for shared path: (((c) * KH) + kh) * KW
    mul.lo.u32 %r_t3, %r_c, %rKH;
    add.u32 %r_t3, %r_t3, %r_kh;
    mul.lo.u32 %r_w_local_base_idx, %r_t3, %rKW;
    // Compute valid kw range to avoid per-iteration bounds checks
    // kw_lo = max(0, -wbase); kw_hi = min(KW, Win - wbase)
    mov.u32 %r_kw_lo, 0;
    setp.lt.s32 %p, %r_wbase_s32, 0;
    sub.s32 %r_tmpk0, 0, %r_wbase_s32;
    cvt.u32.s32 %r_tmpk1, %r_tmpk0;
    @!%p bra L_kwlo_done;
    setp.gt.u32 %p, %r_tmpk1, %rKW;
    @%p mov.u32 %r_kw_lo, %rKW;
    @!%p mov.u32 %r_kw_lo, %r_tmpk1;
    bra L_kwlo_done;
L_kwlo_done:
    cvt.s32.u32 %r_t4, %rWin;
    sub.s32 %r_tmpk0, %r_t4, %r_wbase_s32;
    setp.le.s32 %p, %r_tmpk0, 0;
    @%p mov.u32 %r_kw_hi, 0;
    @%p bra L_kwhi_done;
    cvt.u32.s32 %r_tmpk1, %r_tmpk0;
    setp.gt.u32 %p, %r_tmpk1, %rKW;
    @%p mov.u32 %r_kw_hi, %rKW;
    @!%p mov.u32 %r_kw_hi, %r_tmpk1;
L_kwhi_done:
    // Loop over kernel width kw in [kw_lo, kw_hi)
    mov.u32 %r_kw, %r_kw_lo;
L_kw_loop:
L_kw_vec_loop:
    // If we have at least 4 elements remaining, and input address is 16B-aligned, use vectorized loads
    add.u32 %r_kwp4, %r_kw, 4;
    setp.gt.u32 %p, %r_kwp4, %r_kw_hi;
    @%p bra L_kw_scalar_entry;
    // Compute E = in_base + (wbase + kw) and check 16B alignment (E % 4 == 0)
    cvt.s32.u32 %r_t3, %r_kw;
    add.s32 %r_win_s32, %r_wbase_s32, %r_t3;
    cvt.u32.s32 %r_win_u32, %r_win_s32;
    add.u32 %r_t5, %r_in_base, %r_win_u32; // E
    and.b32 %r_align, %r_t5, 3;
    setp.ne.u32 %p, %r_align, 0;
    @%p bra L_kw_scalar_entry;
    // Vectorized load of 4 input values
    mul.wide.u32 %ofs_bytes, %r_t5, 4;
    add.s64 %addr_inp, %rd_inp, %ofs_bytes;
    ld.global.v4.f32 {%f_in, %f_v1, %f_v2, %f_v3}, [%addr_inp];
    // Prepare base indices for weights
    add.u32 %r_wloc_base_kw, %r_w_local_base_idx, %r_kw;
    add.u32 %r_wglob_base_kw, %r_w_base_idx, %r_kw;
    // Load 4 weights (shared if same co, else global) and accumulate
    // Vectorized load of 4 weights from shared memory when aligned; else scalar fallback
    mul.wide.u32 %ofs_bytes, %r_wloc_base_kw, 4;
    add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
    mul.wide.u32 %ofs_bytes, %r_wglob_base_kw, 4;
    add.s64 %addr_w, %rd_w, %ofs_bytes;
    and.b32 %r_t0, %r_wloc_base_kw, 3;
    setp.eq.u32 %p_vec_ok, %r_t0, 0;
    and.pred %p_and, %p_same, %p_vec_ok;
    @%p_and bra L_w_vec_smem_g;
    bra L_w_vec_fallback_g;
L_w_vec_smem_g:
    ld.shared.v4.f32 {%f_w0, %f_w1, %f_w2, %f_w3}, [%addr_smem];
    bra L_w_vec_loaded_g;
L_w_vec_fallback_g:
    // k = 0
    @%p_same ld.shared.f32 %f_w0, [%addr_smem];
    @!%p_same ld.global.f32 %f_w0, [%addr_w];
    // k = 1
    add.s64 %addr_smem, %addr_smem, 4;
    add.s64 %addr_w, %addr_w, 4;
    @%p_same ld.shared.f32 %f_w1, [%addr_smem];
    @!%p_same ld.global.f32 %f_w1, [%addr_w];
    // k = 2
    add.s64 %addr_smem, %addr_smem, 4;
    add.s64 %addr_w, %addr_w, 4;
    @%p_same ld.shared.f32 %f_w2, [%addr_smem];
    @!%p_same ld.global.f32 %f_w2, [%addr_w];
    // k = 3
    add.s64 %addr_smem, %addr_smem, 4;
    add.s64 %addr_w, %addr_w, 4;
    @%p_same ld.shared.f32 %f_w3, [%addr_smem];
    @!%p_same ld.global.f32 %f_w3, [%addr_w];
L_w_vec_loaded_g:
    // Accumulate 4 FMAs
    fma.rn.f32 %f_acc, %f_in,  %f_w0, %f_acc;
    fma.rn.f32 %f_acc, %f_v1,  %f_w1, %f_acc;
    fma.rn.f32 %f_acc, %f_v2,  %f_w2, %f_acc;
    fma.rn.f32 %f_acc, %f_v3,  %f_w3, %f_acc;
    // Advance kw by 4 and continue vector loop
    add.u32 %r_kw, %r_kw, 4;
    bra L_kw_vec_loop;
L_kw_scalar_entry:
L_kw_scalar_loop:
    setp.ge.u32 %p, %r_kw, %r_kw_hi;
    @%p bra L_end_kw;
    // Scalar iteration for remaining kw values
    cvt.s32.u32 %r_t3, %r_kw;
    add.s32 %r_win_s32, %r_wbase_s32, %r_t3;
    cvt.u32.s32 %r_win_u32, %r_win_s32;
    add.u32 %r_t5, %r_in_base, %r_win_u32;
    mul.wide.u32 %ofs_bytes, %r_t5, 4;
    add.s64 %addr_inp, %rd_inp, %ofs_bytes;
    ld.global.f32 %f_in, [%addr_inp];
    // Shared-memory address for weights: smem_w[w_local_base_idx + kw]
    add.u32 %r_t0, %r_w_local_base_idx, %r_kw;
    mul.wide.u32 %ofs_bytes, %r_t0, 4;
    add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
    // Global-memory address for weights: w[w_base_idx + kw]
    add.u32 %r_t0, %r_w_base_idx, %r_kw;
    mul.wide.u32 %ofs_bytes, %r_t0, 4;
    add.s64 %addr_w, %rd_w, %ofs_bytes;
    @%p_same ld.shared.f32 %f_w, [%addr_smem];
    @!%p_same ld.global.f32 %f_w,  [%addr_w];
    fma.rn.f32 %f_acc, %f_in, %f_w, %f_acc;
